date_parts = [int(part) for part in current_date_and_time['date'].split('-')]
current_year, current_month, current_day = date_parts
if current_day > 1:
    previous_year, previous_month, previous_day = current_year, current_month, current_day - 1
else:
    previous_month = current_month - 1
    previous_year = current_year
    if previous_month == 0:
        previous_month = 12
        previous_year -= 1
    leap_year = previous_year % 4 == 0 and (previous_year % 100 != 0 or previous_year % 400 == 0)
    month_lengths = [31, 29 if leap_year else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    previous_day = month_lengths[previous_month - 1]
yesterday_date = f'{previous_year:04d}-{previous_month:02d}-{previous_day:02d}'
def words_in(text):
    return ''.join(ch.lower() if ch.isalnum() else ' ' for ch in text).split()
def amount_from_line(line):
    source = line[line.rfind('$') + 1:] if '$' in line else line
    numeric_text = ''.join(ch if ch.isdigit() or ch == '.' else ' ' for ch in source)
    values = []
    for token in numeric_text.split():
        if token.count('.') <= 1 and any(ch.isdigit() for ch in token):
            value = float(token)
            if value > 0:
                values.append(value)
    return round(values[-1], 2) if values else None
first_name_counts = {}
for contact in coworker_contacts:
    first_key = contact['first_name'].strip().lower()
    first_name_counts[first_key] = first_name_counts.get(first_key, 0) + 1
parsed_note_candidates = []
for note in dinner_note_details:
    shares = {}
    lines = [line.strip() for line in note['content'].splitlines() if line.strip()]
    for contact in coworker_contacts:
        first_key = contact['first_name'].strip().lower()
        last_key = contact['last_name'].strip().lower()
        email_key = contact['email'].strip().lower()
        for line in lines:
            line_lower = line.lower()
            line_words = words_in(line)
            name_matches = first_key in line_words and (last_key in line_words or first_name_counts[first_key] == 1)
            if email_key in line_lower or name_matches:
                parsed_amount = amount_from_line(line)
                if parsed_amount is not None:
                    shares[email_key] = {'name': (contact['first_name'] + ' ' + contact['last_name']).strip(), 'email': contact['email'], 'amount': parsed_amount}
                    break
    searchable_text = (note['title'] + ' ' + note['content']).lower()
    keyword_score = sum(1 for keyword in ['dinner', 'coworker', 'colleague', 'share'] if keyword in searchable_text)
    parsed_note_candidates.append({'note': note, 'shares': shares, 'rank': (len(shares), keyword_score, note['updated_at'])})
if not parsed_note_candidates:
    raise ValueError('No candidate dinner note was returned')
selected_note_candidate = max(parsed_note_candidates, key=lambda candidate: candidate['rank'])
selected_dinner_note = selected_note_candidate['note']
share_records = list(selected_note_candidate['shares'].values())
if not share_records:
    raise ValueError('No coworker shares could be derived from the candidate notes')
print({'selected_note_id': selected_dinner_note['note_id'], 'selected_note_title': selected_dinner_note['title'], 'yesterday_date': yesterday_date, 'shares': [{'name': row['name'], 'amount': row['amount']} for row in share_records]})

received_amounts_by_sender = {}
for transaction in received_transactions:
    sender_email = transaction['sender']['email'].strip().lower()
    received_amounts_by_sender.setdefault(sender_email, []).append(float(transaction['amount']))
payment_targets = []
already_paid = []
for share in share_records:
    email_key = share['email'].strip().lower()
    matching_amounts = received_amounts_by_sender.get(email_key, [])
    has_matching_payment = any(abs(amount - float(share['amount'])) < 0.005 for amount in matching_amounts)
    if has_matching_payment:
        already_paid.append(share)
    else:
        payment_targets.append({'name': share['name'], 'email': share['email'], 'amount': float(share['amount']), 'description': 'Dinner with Colleagues'})
if any(target['amount'] <= 0 for target in payment_targets):
    raise ValueError('A derived request amount is not positive')
print({'already_paid_count': len(already_paid), 'request_count': len(payment_targets), 'requests_to_create': [{'name': target['name'], 'email': target['email'], 'amount': target['amount'], 'description': target['description']} for target in payment_targets]})
